grant execute on function public.ledger_month_is_closed_v1(date),public.ledger_assert_month_open_v1(date),public.ledger_record_source_drift_v1(bigint,text,numeric,jsonb,bigint),public.ledger_close_preflight_v1(date,bigint),public.ledger_close_month_v1(date,text,jsonb,jsonb,text,bigint),public.ledger_create_correction_v1(bigint,numeric,jsonb,timestamptz,date,text,bigint,bigint),public.ledger_sync_pos_sales_v2(jsonb,bigint),public.ledger_sync_recurring_expenses_v2(date,bigint),public.ledger_sync_payroll_company_cost_v2(jsonb,bigint) to service_role;

comment on table public.ledger_month_closures is 'Immutable V1 month-close records. Reopen/delete is intentionally unsupported.';
comment on column public.ledger_transactions.economic_effect_sign is '+1 increases the transaction economic effect; -1 is a linked correction reducing it.';
